import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { WAREHOUSE_SHIPMENTS, fmt } from '../../utils/dummyData';
import './OrderTracking.css';

const OrderTracking = () => {
  const { id } = useParams();
  const shipment = WAREHOUSE_SHIPMENTS.find(s => s._id === id) || WAREHOUSE_SHIPMENTS[0];

  const steps = [
    { label: 'Order Placed', date: 'Jan 15, 2024', completed: true },
    { label: 'Processing', date: 'Jan 15, 2024', completed: true },
    { label: 'Packed', date: 'Jan 16, 2024', completed: true },
    { label: 'In Transit', date: 'Jan 17, 2024', completed: shipment.status === 'in_transit' || shipment.status === 'delivered' },
    { label: 'Delivered', date: shipment.status === 'delivered' ? 'Jan 18, 2024' : 'Est. Jan 19', completed: shipment.status === 'delivered' }
  ];

  return (
    <div className="tracking-page container">
      <div className="tracking-header">
        <h1>Track Your Order</h1>
        <p>Tracking ID: {shipment.trackingId}</p>
      </div>

      <div className="tracking-content">
        <div className="tracking-timeline">
          {steps.map((step, i) => (
            <div className={`tracking-step ${step.completed ? 'completed' : ''}`} key={i}>
              <div className="step-indicator">
                <div className="step-dot"></div>
                {i < steps.length - 1 && <div className="step-line"></div>}
              </div>
              <div className="step-info">
                <span className="step-label">{step.label}</span>
                <span className="step-date">{step.date}</span>
              </div>
            </div>
          ))}
        </div>

        <div className="tracking-details">
          <div className="detail-card">
            <h3>Order Details</h3>
            <div className="detail-row">
              <span>Customer</span>
              <span>{shipment.customer}</span>
            </div>
            <div className="detail-row">
              <span>Product</span>
              <span>{shipment.product}</span>
            </div>
            <div className="detail-row">
              <span>Delivery Address</span>
              <span>{shipment.address}</span>
            </div>
            <div className="detail-row">
              <span>Current Status</span>
              <span className={`status ${shipment.status}`}>{shipment.status.replace('_', ' ')}</span>
            </div>
          </div>

          <Link to="/my-orders" className="btn btn-outline">Back to Orders</Link>
        </div>
      </div>
    </div>
  );
};

export default OrderTracking;
